WITH flattened_attrs AS (SELECT id, plan, currency, tier_limits, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers WHERE currency = 'USD') SELECT *, SUM(entry_price) OVER (PARTITION BY currency ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_entry_price, SUM(entry_price) OVER (PARTITION BY currency, plan ORDER BY entry_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_entry_price_2 FROM flattened_attrs
